# Function to calculate the sum of the first 10 prime numbers
def sum_of_first_10_primes():
    prime_numbers = []
    num = 2
    while len(prime_numbers) < 10:
        is_prime = True
        for i in range(2, int(num ** 0.5) + 1):
            if num % i == 0:
                is_prime = False
                break
        if is_prime:
            prime_numbers.append(num)
        num += 1
    return sum(prime_numbers)

# Print the sum of the first 10 prime numbers
print(sum_of_first_10_primes())
